// Shared in-memory state survives Navigator.pop but resets on app restart.
class MovieLibrary extends ChangeNotifier {
  final Set<String> _favorites = {};
  final Map<String, int> _ratings = {};
  bool isFavorite(String id) => _favorites.contains(id);
  int? ratingFor(String id) => _ratings[id];
  int get favoriteCount => _favorites.length;

  void toggleFavorite(String id) {
    if (!_favorites.remove(id)) _favorites.add(id);
    notifyListeners();
  }

  void rate(String id, int rating) {
    assert(rating >= 1 && rating <= 10);
    _ratings[id] = rating;
    notifyListeners();
  }
}

