class MoviePoster extends StatelessWidget {
  const MoviePoster({super.key, required this.movie, this.hero = false});
  final Movie movie;
  final bool hero;

  @override
  Widget build(BuildContext context) {
    final image = ClipRRect(
      borderRadius: BorderRadius.circular(14),
      child: Image.network(
        movie.posterUrl,
        fit: BoxFit.cover,
        width: double.infinity,
        height: double.infinity,
        semanticLabel: '${movie.title} poster',
        loadingBuilder: (context, child, progress) => progress == null
            ? child
            : const ColoredBox(
                color: Color(0xFF303849),
                child: Center(child: CircularProgressIndicator(strokeWidth: 2)),
              ),
        errorBuilder: (context, error, stackTrace) => const ColoredBox(
          color: Color(0xFF303849),
          child: Center(child: Icon(Icons.movie_outlined, size: 44)),
        ),
      ),
    );
    return hero ? Hero(tag: 'poster-${movie.id}', child: image) : image;
  }
}

