class MovieDetailScreen extends StatelessWidget {
  const MovieDetailScreen({
    super.key,
    required this.movie,
    required this.library,
  });
  final Movie movie;
  final MovieLibrary library;

  Future<void> _rateMovie(BuildContext context) async {
    var selected = library.ratingFor(movie.id) ?? 8;
    final rating = await showDialog<int>(
      context: context,
      builder: (context) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          title: Text('Rate ${movie.title}'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                '$selected / 10',
                style: Theme.of(context).textTheme.headlineMedium,
              ),
              Slider(
                value: selected.toDouble(),
                min: 1,
                max: 10,
                divisions: 9,
                label: '$selected',
                onChanged: (value) =>
                    setDialogState(() => selected = value.round()),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(context, selected),
              child: const Text('Save rating'),
            ),
          ],
        ),
      ),
    );
    if (rating != null) library.rate(movie.id, rating);
  }

  Future<void> _shareMovie(BuildContext context) async {
    final text =
        '${movie.title} (${movie.year})\nRating: ${movie.rating.toStringAsFixed(1)}/10\n'
        'Genres: ${movie.genres.join(', ')}\n\n${movie.overview}';
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Share movie'),
        content: SingleChildScrollView(child: SelectableText(text)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Close'),
          ),
          FilledButton.icon(
            icon: const Icon(Icons.copy),
            label: const Text('Copy details'),
            onPressed: () async {
              try {
                await Clipboard.setData(ClipboardData(text: text));
                if (!dialogContext.mounted) return;
                Navigator.pop(dialogContext);
                if (context.mounted) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(
                      content: Text('Movie details copied to clipboard.'),
                    ),
                  );
                }
              } catch (_) {
                if (context.mounted) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Could not copy. Select the text to copy it manually.',
                      ),
                    ),
                  );
                }
              }
            },
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Movie details')),
      body: SafeArea(
