            child: ListView(
              padding: const EdgeInsets.only(bottom: 24),
              children: [
                // A gradient keeps the foreground poster and metadata readable.
                SizedBox(
                  height: 280,
                  child: Stack(
                    fit: StackFit.expand,
                    children: [
                      MoviePoster(movie: movie),
                      const DecoratedBox(
                        decoration: BoxDecoration(
