// Source: lib/screens/home.dart

class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});
  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  final _library = MovieLibrary();
  final _search = TextEditingController();
  String _query = '';
  bool _favoritesOnly = false;

  @override
  void dispose() {
    _library.dispose();
    _search.dispose();
    super.dispose();
  }

  void _openMovie(Movie movie) {
    // Pass the selected Movie object to the new route.
    Navigator.push<void>(
      context,
      MaterialPageRoute<void>(
        builder: (_) => MovieDetailScreen(movie: movie, library: _library),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        leading: const Icon(Icons.movie_filter_outlined),
        title: const Text('Movie Explorer'),
      ),
      body: SafeArea(
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 900),
            child: AnimatedBuilder(
              animation: _library,
              builder: (context, _) {
                final movies = sampleMovies.where((movie) {
                  final matches = '${movie.title} ${movie.genres.join(' ')}'
                      .toLowerCase()
                      .contains(_query);
                  return matches &&
                      (!_favoritesOnly || _library.isFavorite(movie.id));
                }).toList();
                // Header and cards scroll together, including in landscape.
                return ListView.builder(
                  padding: const EdgeInsets.fromLTRB(20, 16, 20, 24),
                  itemCount: movies.length + 2,
                  itemBuilder: (context, index) {
                    if (index == 0) {
                      return Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'Find your next story.',
                            style: Theme.of(context).textTheme.headlineMedium
                                ?.copyWith(fontWeight: FontWeight.bold),
                          ),
                          const SizedBox(height: 8),
                          const Text(
                            'Three unforgettable journeys. Pick a movie to explore.',
                          ),
                          const SizedBox(height: 24),
                          TextField(
                            controller: _search,
                            onChanged: (value) => setState(
                              () => _query = value.trim().toLowerCase(),
                            ),
                            decoration: InputDecoration(
                              hintText: 'Search movies or genres',
                              prefixIcon: const Icon(Icons.search),
                              suffixIcon: _query.isEmpty
                                  ? null
                                  : IconButton(
                                      tooltip: 'Clear search',
                                      icon: const Icon(Icons.close),
                                      onPressed: () {
                                        _search.clear();
                                        setState(() => _query = '');
                                      },
                                    ),
                            ),
                          ),
                          const SizedBox(height: 16),
                          Wrap(
                            spacing: 10,
                            runSpacing: 8,
                            children: [
                              ChoiceChip(
                                label: const Text('All movies'),
                                selected: !_favoritesOnly,
                                onSelected: (_) =>
                                    setState(() => _favoritesOnly = false),
                              ),
                              ChoiceChip(
                                label: Text(
                                  'Favorites (${_library.favoriteCount})',
                                ),
                                selected: _favoritesOnly,
                                onSelected: (_) =>
                                    setState(() => _favoritesOnly = true),
                              ),
                            ],
                          ),
                          const SizedBox(height: 20),
                        ],
                      );
                    }
                    if (index == movies.length + 1) {
                      return Padding(
                        padding: const EdgeInsets.symmetric(vertical: 16),
                        child: Text(
                          movies.isEmpty
                              ? 'No movies found. Try another search or switch to All movies.'
                              : '${movies.length} movies · Select a card to view details',
                          textAlign: TextAlign.center,
                        ),
                      );
                    }
                    final movie = movies[index - 1];
                    return Card(
                      margin: const EdgeInsets.only(bottom: 14),
                      clipBehavior: Clip.antiAlias,
                      child: InkWell(
                        key: ValueKey('movie-${movie.id}'),
                        onTap: () => _openMovie(movie),
                        child: Padding(
                          padding: const EdgeInsets.all(14),
                          child: Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              SizedBox(
                                width: 88,
                                height: 132,
                                child: MoviePoster(movie: movie, hero: true),
                              ),
                              const SizedBox(width: 16),
                              Expanded(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      movie.title,
                                      style: Theme.of(context)
                                          .textTheme
                                          .titleLarge
                                          ?.copyWith(
                                            fontWeight: FontWeight.bold,
                                          ),
                                    ),
                                    const SizedBox(height: 8),
                                    Text('${movie.year} · ${movie.runtime}'),
                                    const SizedBox(height: 6),
                                    Text(
                                      movie.genres.join(' / '),
                                      style: Theme.of(context)
                                          .textTheme
                                          .bodySmall,
                                    ),
                                    const SizedBox(height: 10),
                                    Wrap(
                                      spacing: 12,
                                      runSpacing: 8,
                                      crossAxisAlignment:
                                          WrapCrossAlignment.center,
                                      children: [
                                        Text(
                                          '★ ${movie.rating.toStringAsFixed(1)} / 10',
                                          style: TextStyle(
                                            color: Theme.of(context)
                                                .colorScheme
                                                .primary,
                                          ),
                                        ),
                                        if (_library.isFavorite(movie.id))
                                          const Icon(
                                            Icons.favorite,
                                            color: Colors.pinkAccent,
                                            size: 20,
                                          ),
                                        if (_library.ratingFor(movie.id) !=
                                            null)
                                          Text(
                                            'You: ${_library.ratingFor(movie.id)}/10',
                                          ),
                                      ],
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ),
      ),
    );
  }
}

